#include <algorithm>
#include <cmath>
#include <vector>
struct Account{double capital,risk,lev,comm,slip,delay,contract,tick;int mask=1,symbol=0;int jpy,style,prop=0,positionStyle=0,pendingStyle=0;double stopATR,rr,hold;double bal,peak,dd=0,gain=0,loss=0,cost=0,dayStart;int day=-1,side=0,pending=0,closed=0,blocked=0;double entry=0,stop=0,target=0,qty=0,opened=0,initialRisk=0,fees=0,best=0,stopDue=0,stopNext=0,exitDue=0,pendingAt=0,pendingUntil=0,planStop=0,planTarget=0,planRef=0,lastClient=-1,lastExit=-1;bool locked=false,failed=false;std::vector<double>trades;};
struct Stream{int minutes,index=-1,seen=-1;const double*time,*atr,*structure;const signed char*signal;double bid=0,ask=0;};
struct Engine{Stream streams[2];double last=-1;std::vector<Account>accounts;};
static double unit(const Account&a,double p){return a.contract/(a.jpy?p:1.);}
static double roundp(const Account&a,double p,bool buy){return (buy?std::ceil(p/a.tick-1e-8):std::floor(p/a.tick+1e-8))*a.tick;}
static void finish(Account&a,double px,double t,int reason){px=roundp(a,px-a.side*a.slip,a.side<0);double gross=a.side*(px-a.entry)*a.qty*unit(a,px),fee=a.qty*a.comm,net=gross-fee-a.fees;a.bal+=gross-fee;a.cost+=fee;a.gain+=std::max(0.,net);a.loss-=std::min(0.,net);a.trades.insert(a.trades.end(),{a.opened,t,double(a.side),a.entry,px,a.qty,net,net/a.initialRisk,double(reason),a.initialRisk,double(a.symbol),(t-a.opened)/60000});a.closed++;a.side=0;a.stopDue=0;a.exitDue=0;a.lastExit=t;}
extern "C" void* create(int n0,const double*t0,const signed char*s0,const double*a0,const double*l0,int n1,const double*t1,const signed char*s1,const double*a1,const double*l1,int count,const double*cfg){auto*e=new Engine;e->streams[0]=Stream{n0,-1,-1,t0,a0,l0,s0};e->streams[1]=Stream{n1,-1,-1,t1,a1,l1,s1};for(int i=0;i<count;i++){const double*c=cfg+i*15;Account a;a.contract=c[0];a.tick=c[1];a.comm=c[2];a.slip=c[3];a.risk=c[4];a.lev=c[5];a.stopATR=c[6];a.rr=c[7];a.hold=c[8];a.style=c[9];a.capital=c[10];a.jpy=c[11];a.delay=c[12];a.prop=c[13];a.mask=c[14];a.bal=a.peak=a.dayStart=a.capital;if(a.style!=0&&a.style!=1&&a.style!=2){delete e;return nullptr;}e->accounts.push_back(a);}return e;}
static int quote(Engine&e,int symbol,double t,double b,double s){auto&v=e.streams[symbol];if(!std::isfinite(t)||!std::isfinite(b)||!std::isfinite(s)||b<=0||s<b||t<e.last)return -1;e.last=t;v.bid=b;v.ask=s;while(v.index+1<v.minutes&&v.time[v.index+1]<=t)v.index++;if(v.index<0)return 0;int k=v.index;bool first=v.seen!=k;v.seen=k;int day=int(t/86400000),hour=int(std::fmod(t,86400000)/3600000);bool active=hour>=6&&hour<20;
 for(auto&a:e.accounts){if(a.failed||!(a.mask&(1<<symbol))||((a.side||a.pending)&&a.symbol!=symbol))continue;if(!a.side&&!a.pending){a.symbol=symbol;a.jpy=symbol==1;a.contract=symbol==1?100000:100;a.tick=symbol==1?.001:.01;a.comm=symbol==1?3.5:5.25;a.slip=symbol==1?.001:.075;}bool client=a.lastClient<0||t-a.lastClient>=1000;if(client)a.lastClient=t;if(a.day!=day){if(a.day>=0&&a.side){double carry=(day-a.day)*a.qty*(a.jpy?a.contract:a.contract*(a.side>0?b:s))*.00015; a.bal-=carry;a.cost+=carry;a.fees+=carry;}a.day=day;a.dayStart=a.bal;a.locked=false;}
  if(a.side){double px=a.side>0?b:s;if(a.side*(px-a.stop)<=0)finish(a,px,t,1);else if(a.side*(px-a.target)>=0)finish(a,a.target,t,2);else if(a.stopDue&&t>=a.stopDue){a.stopDue=0;if(a.side*(px-a.stopNext)<=0)finish(a,px,t,8);else a.stop=a.stopNext;}
   if(a.side){if(a.exitDue&&t>=a.exitDue)finish(a,px,t,3);else if(client){double dist=a.initialRisk/(a.qty*unit(a,a.entry));if(!a.exitDue&&(t-a.opened>=a.hold*60000))a.exitDue=t+1000;a.best=std::max(a.best,a.side*(px-a.entry));if(!a.stopDue&&((a.positionStyle==1&&a.best>=dist)||(a.positionStyle==2&&a.best>=2*dist))){double st=a.positionStyle==1?a.entry+a.side*(2*a.comm/unit(a,a.entry)+2*a.slip):a.entry+a.side*std::max(.5*dist,a.best-2*v.atr[k]);if(a.side*(st-a.stop)>.5*a.tick){a.stopNext=roundp(a,st,a.side<0);a.stopDue=t+1000;}}}}
  }
  if(first&&!a.side&&!a.pending&&v.signal[k]&&active&&!a.locked&&!a.failed&&t-v.time[k]<=30000&&t-a.lastExit>=60000&&std::isfinite(v.atr[k])&&std::isfinite(v.structure[k])){
   int side=v.signal[k]>0?1:-1;a.pendingStyle=std::abs(int(v.signal[k]))==3?0:a.style;double px=roundp(a,(side>0?s:b)+side*a.slip,side>0),st=side>0?std::min(px-a.stopATR*v.atr[k],v.structure[k]):std::max(px+a.stopATR*v.atr[k],v.structure[k]);st=roundp(a,st,side<0);double distance=side*(px-st);a.pending=side;a.pendingAt=t+a.delay;a.pendingUntil=t+30000;a.planStop=st;a.planTarget=px+side*distance*a.rr;a.planRef=px;
  }
  if(a.pending&&!a.side&&t>=a.pendingAt){int side=a.pending;a.pending=0;double px=roundp(a,(side>0?s:b)+side*a.slip,side>0),dist=side*(px-a.planStop),expense=s-b+2*a.slip+2*a.comm/unit(a,px),notional=a.jpy?a.contract:a.contract*px;double daily=a.capital*(a.prop==0?.10:a.prop==2?.045:.04),overall=a.capital*(a.prop==0?.50:a.prop==2?.09:.08),room=std::min(daily-(a.dayStart-a.bal),overall-((a.prop>=2?a.capital:a.peak)-a.bal)),budget=std::min(a.bal*a.risk/100.,std::max(0.,room)),q=std::floor(std::min(budget/(dist*unit(a,px)+2*a.comm),a.bal*a.lev/notional)*100)/100;
   if(t>a.pendingUntil||!active||a.locked||a.failed||dist<=0||side*(a.planTarget-px)<=0||side*(px-a.planRef)>.25*dist||expense>.25*dist||s-b>.25*v.atr[k]||q<.01||q*notional/a.lev+q*a.comm>a.bal){a.blocked++;continue;}
   a.side=side;a.positionStyle=a.pendingStyle;a.entry=px;a.stop=a.planStop;a.target=a.planTarget;a.qty=q;a.opened=t;a.initialRisk=q*dist*unit(a,px);a.best=0;a.fees=q*a.comm;a.bal-=a.fees;a.cost+=a.fees;
  }
  double px=a.side>0?b:s,eq=a.bal+(a.side?a.side*(px-a.entry)*a.qty*unit(a,px)-a.qty*a.comm:0);a.peak=std::max(a.peak,eq);a.dd=std::max(a.dd,(a.peak-eq)/a.peak*100);if(eq<=a.dayStart-a.capital*(a.prop==0?.10:a.prop==2?.045:.04))a.locked=true;if(eq<=(a.prop>=2?a.capital:a.peak)-a.capital*(a.prop==0?.50:a.prop==2?.09:.08)){a.failed=true;if(a.side)finish(a,a.side>0?b:s,t,11);}
 }
return 0;}
extern "C" int feed2(void*p,int n0,const double*t0,const double*b0,const double*a0,int n1,const double*t1,const double*b1,const double*a1){auto&e=*static_cast<Engine*>(p);int i=0,j=0;while(i<n0||j<n1){int r;if(j==n1||(i<n0&&t0[i]<=t1[j])){r=quote(e,0,t0[i],b0[i],a0[i]);i++;}else{r=quote(e,1,t1[j],b1[j],a1[j]);j++;}if(r)return r;}return 0;}
extern "C" int summary(void*p,int index,double*out,double*trades,int capacity){auto&e=*static_cast<Engine*>(p);auto&a=e.accounts[index];auto&v=e.streams[a.symbol];if(a.side)finish(a,a.side>0?v.bid:v.ask,e.last,7);if(a.closed>capacity)return -1;std::copy(a.trades.begin(),a.trades.end(),trades);out[0]=(a.bal/a.capital-1)*100;out[1]=a.dd;out[2]=a.closed;out[3]=a.gain;out[4]=a.loss;out[5]=a.bal;out[6]=a.cost;out[7]=a.blocked;out[8]=a.failed;return a.closed;}
extern "C" int snapshot(void*p,int index,double*out,double*trades,int capacity){auto&e=*static_cast<Engine*>(p);auto&a=e.accounts[index];auto&v=e.streams[a.symbol];if(a.closed>capacity)return -1;std::copy(a.trades.begin(),a.trades.end(),trades);out[0]=(a.bal/a.capital-1)*100;out[1]=a.dd;out[2]=a.closed;out[3]=a.gain;out[4]=a.loss;out[5]=a.bal;out[6]=a.cost;out[7]=a.blocked;out[8]=a.failed;out[9]=a.bal+(a.side?a.side*((a.side>0?v.bid:v.ask)-a.entry)*a.qty*unit(a,a.side>0?v.bid:v.ask)-a.qty*a.comm:0);out[10]=a.side;out[11]=a.qty;out[12]=a.side?a.fees:0;return a.closed;}
extern "C" void destroy(void*p){delete static_cast<Engine*>(p);}
